concept.cypher:
CALL {
  MATCH (a:Maven:Artifact)
  WITH a.fqn AS coordinate, collect(a) AS nodes
  WHERE size(nodes) > 1
  CALL {
    // Rank the copies: the one with the most types wins, because that is the
    // one the class-level scan reached. Ties go to the shared .m2 over an
    // isolated repository, then to the lexicographically first path, so the
    // outcome does not depend on the order the projects were scanned in.
    WITH nodes
    UNWIND nodes AS n
    OPTIONAL MATCH (n)-[:CONTAINS]->(t:Type)
    WITH n, count(t) AS types
    ORDER BY types DESC,
             CASE WHEN n.fileName CONTAINS '.m2-isolated' THEN 1 ELSE 0 END ASC,
             n.fileName ASC
    RETURN collect(n) AS ranked
  }
  // 'discard' keeps the properties of the first node in the list, i.e. of the
  // winner.
  //
  // mergeRels MUST stay false. It would fold parallel relationships of the same
  // type between the same two nodes into one and resolve conflicting properties
  // by the same 'discard' policy, and :DEPENDS_ON between two artifacts is
  // already multi-valued in this graph, independently of any duplication: the
  // same edge is recorded once per resolving reactor module, with the scope that
  // module saw. Measured on the store of 2026-09-22: 2002 coordinate pairs carry
  // several edges, 1967 of them with differing scopes (for example
  // org.apache.maven:maven-plugin-api:3.8.6 to maven-model:3.8.6 as both
  // 'compile' and 'provided'). Folding would silently pick one of them.
  // With mergeRels false every relationship is re-pointed and nothing is lost.
  // No copy of a coordinate has a relationship to its own twin (verified), so
  // the merge cannot produce self-loops either.
  CALL apoc.refactor.mergeNodes(ranked, {properties: 'discard', mergeRels: false}) YIELD node
  RETURN count(node) AS mergedCoordinates
}
RETURN mergedCoordinates
